import {validateProtocols} from './protocol-validate.js?v=20261101-short1';
import {metricSummary,manualTask,protocolOf} from './core-metrics.js?v=20261101-short1';
import {publicData} from './public-data.js?v=20261101-short1';
export const categories={math:'数学与推理',code:'代码任务',chinese:'中文表达',data:'数据分析',longcontext:'长文理解',instruction:'指令遵循',visual:'SVG与视觉构造'};
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(x){try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null}catch{return null}}
export const median=xs=>{const a=xs.filter(x=>typeof x==='number'&&Number.isFinite(x)).sort((a,b)=>a-b);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2:null};
export const fmt=(x,n=1)=>typeof x==='number'&&Number.isFinite(x)?x.toLocaleString('zh-CN',{maximumFractionDigits:n}):'—';
export function stats(data,id,category='all'){
 const tasks=data.tasks.filter(t=>category==='all'||t.category===category),taskIds=new Set(tasks.map(t=>t.id));
 const runs=data.runs.filter(r=>r.modelId===id&&taskIds.has(r.taskId)),attempted=runs.filter(r=>r.status!=='skipped'),ok=attempted.filter(r=>r.status==='success');
 const graded=ok.filter(r=>['passed','failed'].includes(r.grading.status)),passed=rs=>rs.filter(r=>r.status==='success'&&r.grading.status==='passed').length;
 const mean=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
 const gradedIds=[...new Set(graded.map(r=>r.taskId))];
 const ruleTasks=tasks.filter(t=>!manualTask(t)&&attempted.some(r=>r.taskId===t.id));
 const ruleGroups=ruleTasks.map(t=>attempted.filter(r=>r.taskId===t.id));
 const costs=attempted.map(r=>r.metrics.cost),known=x=>typeof x==='number'&&Number.isFinite(x),m=k=>median(ok.map(r=>r.metrics[k]));
 const mixedRates=new Set(ok.map(protocolOf)).size>1;
 return {runs:runs.length,attempted:attempted.length,successful:ok.length,tasks:new Set(attempted.map(r=>r.taskId)).size,graded:graded.length,gradedTasks:gradedIds.length,pending:ok.filter(r=>r.grading.status==='pending').length,
  quality:graded.length?passed(graded)/graded.length:null,
  taskQuality:mean(gradedIds.map(t=>{const rs=graded.filter(r=>r.taskId===t);return passed(rs)/rs.length})),
  ruleDelivery:mean(ruleGroups.map(rs=>passed(rs)/rs.length)),ruleTasks:ruleTasks.length,ruleAttempts:ruleGroups.reduce((n,rs)=>n+rs.length,0),
  ruleCost:ruleGroups.length&&ruleGroups.every(rs=>rs.every(r=>known(r.metrics.cost)))?mean(ruleGroups.map(rs=>mean(rs.map(r=>r.metrics.cost)))):null,
  completion:attempted.length?ok.length/attempted.length:null,failure:attempted.length?(attempted.length-ok.length)/attempted.length:null,
  ttft:m('ttftMs'),ttfa:m('ttfaMs'),duration:m('durationMs'),tps:mixedRates?null:m('outputTps'),cps:mixedRates?null:m('charsPerSec'),tpsSamples:mixedRates?0:ok.filter(r=>known(r.metrics.outputTps)).length,cpsSamples:mixedRates?0:ok.filter(r=>known(r.metrics.charsPerSec)).length,cost:m('cost'),unknownCosts:costs.filter(x=>!known(x)).length,
  totalCost:costs.length&&costs.every(known)?costs.reduce((a,b)=>a+b,0):null};
}
export function selectModels(data,{query='',provider='all',sort='name',category='all'}={}){
 const arr=data.models.filter(m=>(provider==='all'||m.provider===provider)&&`${m.name} ${m.provider} ${m.family} ${m.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
 const tasks=data.tasks.filter(t=>category==='all'||t.category===category),ids=new Set(tasks.map(t=>t.id));
 const scoped={...data,tasks,runs:data.runs.filter(r=>ids.has(r.taskId))},core=tasks.some(t=>t.grader.type==='contract'),values=new Map();
 const field={quality:'content',taskQuality:'content',ruleDelivery:'automaticDelivery',completion:'completed',tps:'bodyTps',cps:'chars',ttfa:'ttfa',ttft:'ttft',duration:'duration',cost:'costPerQualified'};
 if(sort!=='name')for(const m of arr)values.set(m.id,sort==='price'?(m.inputPrice??null):core?(metricSummary(scoped,m.id)[field[sort]]??null):(stats(scoped,m.id)[sort]??null));
 return arr.sort((a,b)=>{if(sort==='name')return a.name.localeCompare(b.name,'zh');const av=values.get(a.id),bv=values.get(b.id);if(av===null&&bv===null)return a.name.localeCompare(b.name);if(av===null)return 1;if(bv===null)return -1;return ['quality','ruleDelivery','taskQuality','completion','tps','cps'].includes(sort)?bv-av:av-bv});
}
export function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
export function csv(data){const rows=[['统计范围','模型','服务商','数据类型','独立已测题','规则题数','规则交付率_题目等权含失败','已评回答通过率_题目等权','已评运行通过率','已评分运行','待评运行','完整返回率','尝试数','正文TPS','TPS样本数','首个正文ms','完整耗时ms','成功请求费用中位数USD','规则题等权每次尝试费用USD','全部尝试费用USD','费用未知尝试数','测量协议','内容分_题族等权','内容已评题族','格式全满足率_题族等权','约束细项满足率','端到端正文TPS','新协议正文TPS','新协议TPS样本数','旧口径TPS估计','每个合格结果费用USD','合格费用状态','合格判定覆盖率','重复题组','分歧题组']];data.models.forEach(m=>{const s=stats(data,m.id),c=metricSummary(data,m.id);rows.push([data.meta.description,m.name,m.provider,data.meta.kind,s.tasks,s.ruleTasks,s.ruleDelivery,s.taskQuality,s.quality,s.graded,s.pending,s.completion,s.attempted,s.tps,s.tpsSamples,s.ttfa,s.duration,s.cost,s.ruleCost,s.totalCost,s.unknownCosts,c.protocols.join(' / '),c.content,c.contentFamilies,c.format,c.constraintRate,c.endToEndTps,c.bodyTps,c.bodyTpsSamples,c.legacyTps,c.costPerQualified,c.costState,c.qualificationCoverage,c.repeatedGroups,c.disagreeGroups])});return '\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
export function validateData(input){const d=publicData(input);const fail=s=>{throw new Error(s)};if(!d||d.schemaVersion!=='1.0')fail('需要 schemaVersion = 1.0');if(!d.meta||!['catalog','demo','measured'].includes(d.meta.kind))fail('数据类型必须是 catalog、demo 或 measured');for(const k of ['models','tasks','runs','batches'])if(!Array.isArray(d[k])||d[k].length>50000)fail(k+' 必须是数组且不超过 50000 条');const str=(x,k)=>{if(typeof x!=='string'||x.length>500000)fail(k+' 字符串格式错误')};const number=(x,k,max=Infinity)=>{if(x!==null&&(typeof x!=='number'||!Number.isFinite(x)||x<0||x>max))fail(k+' 应为非负有限数或 null')};const ids={};for(const k of ['models','tasks','runs','batches']){ids[k]=new Set();d[k].forEach(x=>{if(!x||typeof x!=='object')fail(k+' 对象错误');str(x.id,k+'.id');if(!/^[\w.-]{1,120}$/.test(x.id)||ids[k].has(x.id))fail(k+' ID 不合法或重复');ids[k].add(x.id)})}
 d.models.forEach(m=>{for(const k of ['name','provider','family','version','description'])str(m[k],k);if(!Array.isArray(m.tags)||m.tags.some(t=>typeof t!=='string'))fail('tags 格式错误');if(m.sourceUrl!=null&&!safeUrl(m.sourceUrl))fail('来源链接协议不安全');if(m.endpoint!=null&&!safeUrl(m.endpoint))fail('接口链接不安全');for(const k of ['contextWindow','maxOutputTokens','inputPrice','outputPrice','cachedInputPrice'])number(m[k]??null,k);if(!['catalog','demo','measured'].includes(m.status))fail('模型状态错误');if(d.meta.kind==='measured'&&m.status!=='measured')fail('实测集不能含演示或目录模型');if(d.meta.kind==='demo'&&m.status!=='demo')fail('演示集必须使用演示模型')});
 d.tasks.forEach(t=>{for(const k of ['title','prompt','reference'])str(t[k],k);if(!categories[t.category])fail('未知任务类别');if(!Array.isArray(t.rubric)||t.rubric.some(x=>typeof x!=='string'))fail('评分标准格式错误');if(!t.grader||!['exact','contains','json_fields','manual','contract'].includes(t.grader.type))fail('未知评分方式')});
 d.batches.forEach(b=>{str(b.title,'batch.title');if(!['completed','partial','planned'].includes(b.status))fail('批次状态错误');if(!['demo','measured'].includes(b.dataKind))fail('批次类型错误');if(!Array.isArray(b.modelIds)||!Array.isArray(b.taskIds)||b.modelIds.some(id=>!ids.models.has(id))||b.taskIds.some(id=>!ids.tasks.has(id)))fail('批次引用不存在')});
 const batchMap=new Map(d.batches.map(b=>[b.id,b]));
 d.runs.forEach(r=>{if(!ids.models.has(r.modelId)||!ids.tasks.has(r.taskId)||!ids.batches.has(r.batchId))fail('运行引用不存在');if(!['success','error','timeout','skipped'].includes(r.status))fail('运行状态错误');if(!['demo','measured'].includes(r.dataKind)||r.dataKind!==d.meta.kind)fail('运行数据类型与数据集不符');const b=batchMap.get(r.batchId);if(b.dataKind!==r.dataKind||!b.modelIds.includes(r.modelId)||!b.taskIds.includes(r.taskId))fail('运行与批次不一致');str(r.output,'output');if(r.error!=null)str(r.error,'error');if(!r.metrics||!r.grading)fail('缺少指标或评分');for(const k of ['ttftMs','ttfaMs','durationMs','outputTps','charsPerSec','inputTokens','outputTokens','reasoningTokens','cost'])number(r.metrics[k]??null,k);number(r.grading.score??null,'score',1);if(['pending','not_applicable'].includes(r.grading.status)&&r.grading.score!==null)fail('待评或未评记录的分数必须为 null');if(['passed','failed'].includes(r.grading.status)&&r.grading.score==null)fail('已评记录需要分数');if(r.metrics.ttftMs!=null&&r.metrics.ttfaMs!=null&&r.metrics.ttftMs>r.metrics.ttfaMs)fail('TTFT 不能晚于首个正文');for(const k of ['ttftMs','ttfaMs'])if(r.metrics[k]!=null&&r.metrics.durationMs!=null&&r.metrics[k]>r.metrics.durationMs)fail('内容事件不能晚于请求结束');if(r.status!=='success'&&(r.metrics.outputTps!=null||r.metrics.charsPerSec!=null))fail('未完整返回不能提供成功速率');const semantics=r.provenance?.usageSemantics;if(semantics!=null&&!['includes_reasoning','visible_only','unknown'].includes(semantics))fail('未知 token 计数语义');if(r.metrics.reasoningTokens!=null&&r.metrics.outputTokens!=null&&r.metrics.reasoningTokens>r.metrics.outputTokens&&semantics!=='visible_only')fail('推理 token 超过输出 token，需要声明 visible_only 计数语义');for(const k of ['inputTokens','outputTokens','reasoningTokens'])if(r.metrics[k]!=null&&!Number.isInteger(r.metrics[k]))fail('token 用量必须是整数');if(!['passed','failed','pending','not_applicable'].includes(r.grading.status))fail('评分状态错误');if(r.status!=='success'&&r.grading.status!=='not_applicable')fail('未成功请求必须标记 not_applicable')});
 const scan=(x)=>{if(!x||typeof x!=='object')return;for(const [k,v]of Object.entries(x)){if(/^(authorization|api[_-]?key|access[_-]?token|password|secret)$/i.test(k))fail('文件包含凭据字段，请先脱敏');scan(v)}};scan(d);return validateProtocols(d)}
